{
  "contract": "TRYPTO",
  "closure": {
    "site_function": "take_marketing",
    "site_call": ".call",
    "functions": [
      "take_marketing",
      "take_growth"
    ],
    "justification": "Both take_marketing and take_growth modify _ethBal and marketing_balance or growth_balance, which are relevant to the target property."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "take_growth"
    ],
    "nesting_bound": {
      "take_marketing": 1
    }
  },
  "phases": {
    "function": "take_marketing",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .call",
      "to_marker": "after .call"
    },
    "post": {
      "name": "post",
      "from_marker": "after .call",
      "to_marker": "exit"
    },
    "linearization_point": "after .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "marketing_balance + growth_balance == _ethBal + inFlight",
    "stable_formula": "marketing_balance + growth_balance == _ethBal",
    "kind": "additive"
  },
  "composition": {
    "target_property": "marketing_balance + growth_balance <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of marketing_balance and growth_balance is conserved across the callback window, accounting for in-flight ETH."
  }
}
